module tb;
    reg [3:0] in;
    wire [1:0] pos;

    TopModule uut (
        .in(in),
        .pos(pos)
    );

    initial begin
        integer i;
        reg [1:0] expected_pos;

        for (i = 0; i < 16; i = i + 1) begin
            in = i[3:0];
            #1;
            // Determine expected
            if (in[0]) expected_pos = 2'd0;
            else if (in[1]) expected_pos = 2'd1;
            else if (in[2]) expected_pos = 2'd2;
            else if (in[3]) expected_pos = 2'd3;
            else expected_pos = 2'd0;

            if (pos !== expected_pos) begin
                $display("SELFFAIL: in=%b, got=%d, expected=%d", in, pos, expected_pos);
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
